import assert from 'node:assert/strict';
import {readFileSync,mkdirSync,writeFileSync} from 'node:fs';
import {chromium,webkit} from 'playwright';
import {chapterHash} from '../lib/practice-chapters.ts';

const folder='docs/writing-forms-20261102/',out=process.env.KLINK_TEST_OUTPUT||folder+'local',base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:19031';mkdirSync(out,{recursive:true});
const rows=JSON.parse(readFileSync(folder+'import-manifest.json')).newRows.map(x=>x.row),banks=rows.map(row=>({row,exercises:JSON.parse(readFileSync('public'+row.url)).exercises}));
const layouts=[],storage=[],errors=[];
const url=row=>base+'/'+chapterHash({chapter:'writing',activity:'functional-form',collection:row.id,level:row.level,help:row.help});
async function ready(page,e){const task=page.locator(`[data-writing-form-source="${e.exerciseId}"]`);await task.waitFor();await page.waitForFunction(id=>!document.querySelector(`[data-writing-form-source="${id}"] input`).disabled,e.exerciseId);return task;}
async function read(page,id){return page.evaluate(id=>new Promise((resolve,reject)=>{const q=indexedDB.open('klink-writing-form-v1',1);q.onsuccess=()=>{const db=q.result,t=db.transaction('answers'),r=t.objectStore('answers').get(id);t.oncomplete=()=>{resolve(r.result);db.close();};t.onerror=()=>reject(t.error);};q.onerror=()=>reject(q.error);}),id);}
async function visible(page,control){await control.scrollIntoViewIfNeeded();for(let i=0;i<3;i++){const g=await control.evaluate(el=>({box:el.getBoundingClientRect().toJSON(),stage:el.closest('.cp-exercise-stage').getBoundingClientRect().toJSON(),tools:el.closest('.cp-exercise-stage').querySelector('.cp-exercise-tools')?.getBoundingClientRect().toJSON()}));const top=g.tools&&Math.min(g.box.right,g.tools.right)>Math.max(g.box.left,g.tools.left)?g.tools.bottom+6:g.stage.top+8;await page.mouse.move(g.stage.x+g.stage.width*.7,g.stage.y+g.stage.height*.7);await page.mouse.wheel(0,g.box.top-top);await page.waitForTimeout(40);}assert(await control.evaluate(el=>{const r=el.getBoundingClientRect();return r.width>0&&r.height>0&&el.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2));}),'Control must be reachable with real scrolling');}
async function fill(page,task,e,values){for(const field of e.fields){const input=task.locator(`[data-form-field="${field.id}"]`);await visible(page,input);await input.fill(values[field.id]);}}
async function compare(page,task){const button=task.getByRole('button',{name:'Controleer',exact:true});await visible(page,button);await button.click();}
try{for(const[engine,type]of Object.entries({chromium,webkit})){
 const browser=await type.launch({headless:true,...(engine==='chromium'?{channel:'chrome'}:{})});try{
  for(const [width,height]of[[1280,844],[390,844],[320,568],[568,320]])for(const theme of['light','dark']){
   const context=await browser.newContext({viewport:{width,height}}),page=await context.newPage();page.on('pageerror',e=>errors.push({engine,message:e.message}));await page.goto(base);await page.evaluate(theme=>window.TaalrouteAppearance.set(theme),theme);
   for(const level of['alfa-a','alfa-b','alfa-c']){
    const bank=banks.filter(b=>b.row.level===level).sort((a,b)=>Math.max(...b.exercises.map(e=>e.fields.length*100+e.sourceCard.text.length))-Math.max(...a.exercises.map(e=>e.fields.length*100+e.sourceCard.text.length)))[0],e=bank.exercises[0];await page.goto(url(bank.row));const task=await ready(page,e);assert.equal(await task.locator('input').count(),e.fields.length);assert.equal(await task.locator('.functional-source').innerText(),e.sourceCard.text);
    for(const input of await task.locator('input').all()){await visible(page,input);const geometry=await input.evaluate(el=>({box:el.getBoundingClientRect().toJSON(),font:parseFloat(getComputedStyle(el).fontSize)}));assert(geometry.box.height>=44&&geometry.box.width>=100&&geometry.font>=18);}
    await visible(page,task.getByRole('button',{name:'Controleer',exact:true}));assert((await page.evaluate(()=>document.documentElement.scrollWidth))<=width+1);assert.equal(await task.locator('[data-word-audio-missing]').count(),0);
    if(width===390&&theme==='light')await page.screenshot({path:`${out}/layout-${engine}-${level}.png`});layouts.push({engine,width,height,theme,level,sourceId:e.exerciseId,allFieldsAndCheckReachable:true,readableHouseTypography:true,noHorizontalOverflow:true});
   }await context.close();
  }
  const bank=banks[0],e=bank.exercises[0],models=Object.fromEntries(e.fields.map(f=>[f.id,f.acceptedAnswers[0]]));
  {const context=await browser.newContext({viewport:{width:390,height:844}});await context.addInitScript(()=>{const original=Object.getOwnPropertyDescriptor(IDBObjectStore.prototype,'put').value;IDBObjectStore.prototype.put=function(...args){if(window.formFailWrites&&this.transaction.db.name==='klink-writing-form-v1')throw new DOMException('Test quota failure','QuotaExceededError');return original.apply(this,args);};});const page=await context.newPage();await page.goto(url(bank.row));const task=await ready(page,e);await fill(page,task,e,models);await page.waitForFunction(id=>document.querySelector(`[data-writing-form-source="${id}"] input`).value.length>0,e.exerciseId);await page.evaluate(()=>{window.formFailWrites=true;});await compare(page,task);await task.getByRole('alert').waitFor();assert(await page.locator('[data-practice-next]').isDisabled());assert.equal((await read(page,e.exerciseId))?.first,undefined);assert.deepEqual(await task.locator('input').evaluateAll(xs=>xs.map(x=>x.value)),e.fields.map(f=>models[f.id]));await page.evaluate(()=>{window.formFailWrites=false;});await compare(page,task);await page.waitForFunction(id=>document.querySelector(`[data-exercise-id="${id}"]`)?.dataset.practiceReady==='true',e.exerciseId);assert.deepEqual((await read(page,e.exerciseId)).first,models);storage.push({engine,case:'quota-failure-and-recovery',ownInputPreserved:true,noFalseCompletion:true});await context.close();}
  {const context=await browser.newContext(),page=await context.newPage();await page.goto(base);const unknown={version:99,draft:{future:'Niet overschrijven'}};await page.evaluate(({id,unknown})=>new Promise((resolve,reject)=>{const q=indexedDB.open('klink-writing-form-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('answers');q.onsuccess=()=>{const db=q.result,t=db.transaction('answers','readwrite');t.objectStore('answers').put(unknown,id);t.oncomplete=()=>{db.close();resolve();};t.onerror=()=>reject(t.error);};}),{id:e.exerciseId,unknown});await page.goto(url(bank.row));const task=page.locator(`[data-writing-form-source="${e.exerciseId}"]`);await task.getByRole('alert').waitFor();assert(await task.locator('input').first().isDisabled());assert(await page.locator('[data-practice-next]').isDisabled());assert.deepEqual(await read(page,e.exerciseId),unknown);storage.push({engine,case:'unknown-record-version',recordUnchanged:true,noFalseCompletion:true});await context.close();}
  {const context=await browser.newContext({viewport:{width:390,height:844}}),a=await context.newPage(),b=await context.newPage();await a.goto(url(bank.row));await b.goto(url(bank.row));const ta=await ready(a,e),tb=await ready(b,e),first=Object.fromEntries(e.fields.map((f,i)=>[f.id,'  Eigen antwoord '+i+'  ']));await fill(a,ta,e,first);await compare(a,ta);await ta.getByRole('button',{name:'Bewaar voor bespreking',exact:true}).waitFor();await fill(b,tb,e,models);await compare(b,tb);await b.waitForFunction(id=>document.querySelector(`[data-exercise-id="${id}"]`)?.dataset.practiceReady==='true',e.exerciseId);let saved=await read(a,e.exerciseId);assert.deepEqual(saved.first,first);assert.deepEqual(saved.last,models);const control=ta.locator('input').first();await visible(a,control);await control.fill(' Nieuw concept ');await a.waitForFunction(id=>document.querySelector(`[data-writing-form-source="${id}"] input`).value===' Nieuw concept ',e.exerciseId);for(let i=0;i<30;i++){saved=await read(a,e.exerciseId);if(saved.draft[e.fields[0].id]===' Nieuw concept ')break;await a.waitForTimeout(20);}assert.deepEqual(saved.first,first);assert.deepEqual(saved.last,models);assert.equal(saved.draft[e.fields[0].id],' Nieuw concept ');storage.push({engine,case:'two-stale-tabs',immutableFirstPreserved:true,latestSubmissionPreservedDuringNewDraft:true,rawWhitespacePreserved:true});await context.close();}
 }finally{await browser.close();}
}}finally{writeFileSync(out+'/layout-storage.json',JSON.stringify({base,layouts,storage,errors,physicalPhoneAndKeyboardTested:false,audioMocked:false},null,2)+'\n');}
assert.equal(layouts.length,48);assert.equal(storage.length,6);assert.deepEqual(errors,[]);console.log('Passed48 source-form layouts and6 storage failure/version/two-tab cases in Chromium/WebKit.');
